import { Table, Tag, Space, Typography, Modal, Button, InputNumber, Input, App as AntApp } from 'antd';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useState } from 'react';
import { api, getErrorMessage } from '../../lib/api';
import type { Charge } from '@phison/types';
import { formatETB, formatDate } from '../../lib/formatters';

const { Title, Text } = Typography;

const STATUS_COLORS: Record<string, string> = {
  issued: 'blue', partially_paid: 'orange', paid: 'green', overdue: 'red', cancelled: 'default',
};

export default function ResidentCharges() {
  const { message } = AntApp.useApp();
  const qc = useQueryClient();
  const [payModal, setPayModal] = useState<Charge | null>(null);
  const [amount, setAmount] = useState(0);
  const [reference, setReference] = useState('');
  const [fee, setFee] = useState(0);

  const { data: charges = [], isLoading } = useQuery({
    queryKey: ['my-charges'],
    queryFn: () => api.get<Charge[]>('/payments/charges').then(r => r.data),
  });

  const payMutation = useMutation({
    mutationFn: () =>
      api.post(`/payments/resident/online/${payModal?.id}`, {
        amount: Math.round(amount * 100),
        transactionFee: Math.round(fee * 100),
        reference,
      }),
    onSuccess: () => {
      message.success('Payment submitted — awaiting admin confirmation');
      qc.invalidateQueries({ queryKey: ['my-charges'] });
      setPayModal(null);
    },
    onError: (e) => message.error(getErrorMessage(e)),
  });

  const columns = [
    { title: 'Type', dataIndex: 'allocationId', key: 'type' },
    { title: 'Amount', dataIndex: 'amount', key: 'amount', render: (a: number) => formatETB(a) },
    { title: 'Paid', dataIndex: 'paidAmount', key: 'paid', render: (a: number) => formatETB(a) },
    {
      title: 'Outstanding', key: 'outstanding',
      render: (_: unknown, r: Charge) => {
        const os = r.amount - r.paidAmount;
        return <Text strong style={{ color: os > 0 ? '#ff4d4f' : '#52c41a' }}>{formatETB(os)}</Text>;
      },
    },
    { title: 'Due Date', dataIndex: 'dueDate', key: 'dueDate', render: formatDate },
    {
      title: 'Status', dataIndex: 'status', key: 'status',
      render: (s: string) => <Tag color={STATUS_COLORS[s]}>{s.replace(/_/g, ' ')}</Tag>,
    },
    {
      title: 'Actions', key: 'actions',
      render: (_: unknown, record: Charge) => (
        record.status !== 'paid' && record.status !== 'cancelled' && (
          <Button type="primary" size="small" onClick={() => { setPayModal(record); setAmount((record.amount - record.paidAmount) / 100); }}>
            Pay
          </Button>
        )
      ),
    },
  ];

  return (
    <Space direction="vertical" size={16} style={{ width: '100%' }}>
      <Title level={4} style={{ margin: 0 }}>My Charges</Title>
      <Table dataSource={charges} columns={columns} rowKey="id" loading={isLoading} />

      <Modal
        title="Make a Payment"
        open={!!payModal}
        onCancel={() => setPayModal(null)}
        onOk={() => payMutation.mutate()}
        confirmLoading={payMutation.isPending}
        okText="Submit Payment"
      >
        <Space direction="vertical" style={{ width: '100%' }}>
          <Text>Outstanding: <strong>{payModal ? formatETB(payModal.amount - payModal.paidAmount) : ''}</strong></Text>
          <Space direction="vertical" style={{ width: '100%' }}>
            <Text>Amount (ETB)</Text>
            <InputNumber min={0.01} precision={2} value={amount} onChange={v => setAmount(v ?? 0)} style={{ width: '100%' }} />
          </Space>
          <Space direction="vertical" style={{ width: '100%' }}>
            <Text>Transaction Fee (ETB)</Text>
            <InputNumber min={0} precision={2} value={fee} onChange={v => setFee(v ?? 0)} style={{ width: '100%' }} />
          </Space>
          <Space direction="vertical" style={{ width: '100%' }}>
            <Text type="secondary">Total you will pay: <strong>{formatETB(Math.round((amount + fee) * 100))}</strong></Text>
          </Space>
          <Space direction="vertical" style={{ width: '100%' }}>
            <Text>Payment Reference</Text>
            <Input value={reference} onChange={e => setReference(e.target.value)} placeholder="Transaction ID or reference" />
          </Space>
        </Space>
      </Modal>
    </Space>
  );
}
